;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; ECS Systems Processing for MSX
;; Generated by MSX Retro Game IDE
;;
;; Core game systems that process components
;; Includes rendering, physics, animation, AI, etc.
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

; Include dependencies
INCLUDE "ecs_memory_manager.asm"
INCLUDE "ecs_entity_system.asm"
INCLUDE "ecs_component_registry.asm"

; System execution order flags
SYSTEMS_ENABLED:        DB 0xFF     ; Bitmask for enabled systems
FRAME_COUNTER:          DW 0        ; Global frame counter

; System bit flags
SYSTEM_PHYSICS          EQU 0
SYSTEM_AI               EQU 1
SYSTEM_ANIMATION        EQU 2
SYSTEM_COLLISION        EQU 3
SYSTEM_RENDERER         EQU 4
SYSTEM_SOUND            EQU 5
SYSTEM_SPAWNER          EQU 6
SYSTEM_PROJECTILE       EQU 7

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Update all active systems
;; Input: None
;; Output: None
;; Destroys: All registers
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
UPDATE_ALL_SYSTEMS:
    ; Increment frame counter
    LD HL, (FRAME_COUNTER)
    INC HL
    LD (FRAME_COUNTER), HL
    
    ; Check which systems are enabled and call them in order
    LD A, (SYSTEMS_ENABLED)
    
    ; Physics System (before collision)
    BIT SYSTEM_PHYSICS, A
    CALL NZ, PHYSICS_SYSTEM
    
    ; AI System
    BIT SYSTEM_AI, A
    CALL NZ, AI_SYSTEM
    
    ; Animation System
    BIT SYSTEM_ANIMATION, A
    CALL NZ, ANIMATION_SYSTEM
    
    ; Collision System (after physics and movement)
    BIT SYSTEM_COLLISION, A
    CALL NZ, COLLISION_SYSTEM
    
    ; Projectile System
    BIT SYSTEM_PROJECTILE, A
    CALL NZ, PROJECTILE_SYSTEM
    
    ; Spawner System
    BIT SYSTEM_SPAWNER, A
    CALL NZ, SPAWNER_SYSTEM
    
    ; Sound System
    BIT SYSTEM_SOUND, A
    CALL NZ, SOUND_SYSTEM
    
    ; Renderer System (last, for display)
    BIT SYSTEM_RENDERER, A
    CALL NZ, RENDERER_SYSTEM
    
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Physics System - Updates entity positions
;; Input: None
;; Output: None
;; Destroys: All registers
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
PHYSICS_SYSTEM:
    LD B, 0                     ; B = current entity ID

PHYSICS_SYSTEM_LOOP:
    LD A, B
    CP MAX_ENTITIES
    RET NC                      ; Done with all entities
    
    ; Check if entity is active
    CALL GET_ENTITY_PTR
    LD A, (HL)
    OR A
    JP Z, PHYSICS_SYSTEM_NEXT
    
    ; Get Transform component
    LD A, B
    LD B, COMP_ID_TRANSFORM
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JP Z, PHYSICS_SYSTEM_CHECK_PHYSICS ; No transform, check physics
    LD (TEMP_TRANSFORM_PTR), HL
    
    ; Get Physics component
    LD A, (TEMP_ENTITY_ID)
    LD B, COMP_ID_PHYSICS
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JP Z, PHYSICS_SYSTEM_NEXT   ; No physics component
    
    ; Apply velocity to position
    ; velX(2), velY(2), accX(2), accY(2), mass(2), friction(2)
    LD DE, HL                   ; DE = physics component
    LD HL, (TEMP_TRANSFORM_PTR) ; HL = transform component
    
    ; Update X position: x += velX
    LD A, (DE)                  ; velX low
    ADD A, (HL)                 ; + x low
    LD (HL), A
    INC DE
    INC HL
    LD A, (DE)                  ; velX high
    ADC A, (HL)                 ; + x high + carry
    LD (HL), A
    INC DE
    INC HL
    
    ; Update Y position: y += velY
    LD A, (DE)                  ; velY low
    ADD A, (HL)                 ; + y low
    LD (HL), A
    INC DE
    INC HL
    LD A, (DE)                  ; velY high
    ADC A, (HL)                 ; + y high + carry
    LD (HL), A
    
PHYSICS_SYSTEM_CHECK_PHYSICS:
PHYSICS_SYSTEM_NEXT:
    INC B
    JP PHYSICS_SYSTEM_LOOP

; Temporary storage for physics system
TEMP_ENTITY_ID:             DB 0
TEMP_TRANSFORM_PTR:         DW 0

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Animation System - Updates sprite animations
;; Input: None
;; Output: None
;; Destroys: All registers
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
ANIMATION_SYSTEM:
    LD B, 0                     ; B = current entity ID

ANIMATION_SYSTEM_LOOP:
    LD A, B
    CP MAX_ENTITIES
    RET NC
    
    ; Check if entity is active
    CALL GET_ENTITY_PTR
    LD A, (HL)
    OR A
    JP Z, ANIMATION_SYSTEM_NEXT
    
    ; Get Animation component
    LD A, B
    LD B, COMP_ID_ANIMATION
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JP Z, ANIMATION_SYSTEM_NEXT
    
    ; Check if animation is playing
    PUSH HL
    LD BC, 7                    ; Offset to playing flag
    ADD HL, BC
    LD A, (HL)
    OR A
    POP HL
    JP Z, ANIMATION_SYSTEM_NEXT ; Not playing
    
    ; Update frame timer and advance frame
    ; currentFrame(2), frameTime(2), frameCount(2), looping(1), playing(1)
    PUSH HL
    INC HL
    INC HL                      ; Point to frameTime
    LD E, (HL)
    INC HL
    LD D, (HL)                  ; DE = frameTime
    DEC DE                      ; Decrement frame time
    LD (HL), D
    DEC HL
    LD (HL), E
    
    ; Check if frame time expired
    LD A, D
    OR E
    POP HL
    JP NZ, ANIMATION_SYSTEM_NEXT ; Frame time not expired
    
    ; Advance to next frame
    LD E, (HL)                  ; Current frame low
    INC HL
    LD D, (HL)                  ; Current frame high
    INC DE                      ; Next frame
    
    ; Check against frame count
    PUSH HL
    INC HL
    INC HL
    INC HL                      ; Point to frameCount
    LD C, (HL)
    INC HL
    LD B, (HL)                  ; BC = frameCount
    
    ; Compare current frame with frame count
    LD A, E
    CP C
    JR NZ, ANIMATION_FRAME_OK
    LD A, D
    CP B
    JR NZ, ANIMATION_FRAME_OK
    
    ; Frame >= frameCount, check looping
    INC HL                      ; Point to looping flag
    LD A, (HL)
    OR A
    JR Z, ANIMATION_STOP        ; Not looping, stop
    
    ; Loop back to frame 0
    LD DE, 0
    JR ANIMATION_UPDATE_FRAME

ANIMATION_STOP:
    ; Stop animation
    INC HL                      ; Point to playing flag
    XOR A
    LD (HL), A
    POP HL
    JP ANIMATION_SYSTEM_NEXT

ANIMATION_FRAME_OK:
ANIMATION_UPDATE_FRAME:
    POP HL
    LD (HL), E                  ; Update current frame
    INC HL
    LD (HL), D
    
    ; Reset frame time to default (e.g., 4 frames)
    INC HL
    LD (HL), 4
    INC HL
    XOR A
    LD (HL), A

ANIMATION_SYSTEM_NEXT:
    INC B
    JP ANIMATION_SYSTEM_LOOP

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; AI System - Updates AI behaviors
;; Input: None
;; Output: None
;; Destroys: All registers
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
AI_SYSTEM:
    LD B, 0

AI_SYSTEM_LOOP:
    LD A, B
    CP MAX_ENTITIES
    RET NC
    
    ; Check if entity is active
    CALL GET_ENTITY_PTR
    LD A, (HL)
    OR A
    JP Z, AI_SYSTEM_NEXT
    
    ; Get AI component
    LD A, B
    LD B, COMP_ID_AI
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JP Z, AI_SYSTEM_NEXT
    
    ; Process AI based on type
    LD A, (HL)                  ; Get AI type
    CP 1
    JP Z, AI_BASIC_MOVEMENT
    CP 2
    JP Z, AI_SIMPLE_PATROL
    ; Add more AI types here
    
AI_SYSTEM_NEXT:
    INC B
    JP AI_SYSTEM_LOOP

AI_BASIC_MOVEMENT:
    ; Simple AI that moves toward target
    ; Implementation depends on your specific AI needs
    RET

AI_SIMPLE_PATROL:
    ; Simple patrol AI
    ; Implementation depends on your specific AI needs
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Collision System - Handles collision detection
;; Input: None
;; Output: None
;; Destroys: All registers
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
COLLISION_SYSTEM:
    LD B, 0                     ; B = first entity

COLLISION_OUTER_LOOP:
    LD A, B
    CP MAX_ENTITIES-1
    RET NC
    
    ; Check if first entity is active and has collision
    CALL GET_ENTITY_PTR
    LD A, (HL)
    OR A
    JP Z, COLLISION_OUTER_NEXT
    
    LD A, B
    LD B, COMP_ID_COLLISION
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JP Z, COLLISION_OUTER_NEXT
    LD (COLLISION_A_PTR), HL
    
    ; Get transform of first entity
    LD A, (COLLISION_ENTITY_A)
    LD B, COMP_ID_TRANSFORM
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JP Z, COLLISION_OUTER_NEXT
    LD (COLLISION_A_TRANSFORM), HL
    
    ; Check against all other entities
    LD A, (COLLISION_ENTITY_A)
    INC A
    LD C, A                     ; C = second entity

COLLISION_INNER_LOOP:
    LD A, C
    CP MAX_ENTITIES
    JP NC, COLLISION_OUTER_NEXT
    
    ; Check if second entity is active and has collision
    LD B, C
    CALL GET_ENTITY_PTR
    LD A, (HL)
    OR A
    JP Z, COLLISION_INNER_NEXT
    
    LD A, C
    LD B, COMP_ID_COLLISION
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JP Z, COLLISION_INNER_NEXT
    LD (COLLISION_B_PTR), HL
    
    ; Get transform of second entity
    LD A, C
    LD B, COMP_ID_TRANSFORM
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JP Z, COLLISION_INNER_NEXT
    LD (COLLISION_B_TRANSFORM), HL
    
    ; Perform AABB collision check
    CALL CHECK_AABB_COLLISION
    OR A
    CALL NZ, HANDLE_COLLISION   ; Call collision handler if collision detected

COLLISION_INNER_NEXT:
    INC C
    JP COLLISION_INNER_LOOP

COLLISION_OUTER_NEXT:
    LD A, B
    LD (COLLISION_ENTITY_A), A
    INC B
    JP COLLISION_OUTER_LOOP

; Collision system variables
COLLISION_ENTITY_A:         DB 0
COLLISION_A_PTR:            DW 0
COLLISION_A_TRANSFORM:      DW 0
COLLISION_B_PTR:            DW 0
COLLISION_B_TRANSFORM:      DW 0

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Check AABB collision between two entities
;; Input: Collision data pointers set in variables
;; Output: A = 1 if collision, 0 if no collision
;; Destroys: BC, DE, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
CHECK_AABB_COLLISION:
    ; This is a simplified AABB collision check
    ; In practice, you'd compare bounding boxes
    ; For now, return no collision
    XOR A
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Handle collision between two entities
;; Input: Entity IDs in COLLISION_ENTITY_A and current entity
;; Output: None
;; Destroys: All registers
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
HANDLE_COLLISION:
    ; Add your collision response logic here
    ; This could trigger damage, bouncing, etc.
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Renderer System - Updates visual display
;; Input: None
;; Output: None
;; Destroys: All registers
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
RENDERER_SYSTEM:
    ; Clear sprite table or prepare for rendering
    CALL CLEAR_SPRITE_TABLE
    
    LD B, 0
    LD C, 0                     ; C = sprite index

RENDERER_SYSTEM_LOOP:
    LD A, B
    CP MAX_ENTITIES
    RET NC
    
    ; Check if entity is active
    CALL GET_ENTITY_PTR
    LD A, (HL)
    OR A
    JP Z, RENDERER_SYSTEM_NEXT
    
    ; Get Renderer component
    LD A, B
    LD B, COMP_ID_RENDERER
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JP Z, RENDERER_SYSTEM_NEXT
    
    ; Check if visible
    PUSH HL
    INC HL
    INC HL
    INC HL                      ; Point to visible flag
    LD A, (HL)
    POP HL
    OR A
    JP Z, RENDERER_SYSTEM_NEXT  ; Not visible
    
    ; Get Transform component for position
    LD A, (RENDERER_CURRENT_ENTITY)
    LD B, COMP_ID_TRANSFORM
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JP Z, RENDERER_SYSTEM_NEXT  ; No transform
    
    ; Render sprite at position
    CALL RENDER_SPRITE
    INC C                       ; Next sprite slot

RENDERER_SYSTEM_NEXT:
    LD A, B
    LD (RENDERER_CURRENT_ENTITY), A
    INC B
    JP RENDERER_SYSTEM_LOOP

RENDERER_CURRENT_ENTITY:    DB 0

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Clear sprite table (MSX specific)
;; Input: None
;; Output: None
;; Destroys: BC, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
CLEAR_SPRITE_TABLE:
    ; Clear sprite attribute table
    ; This is MSX-specific - adapt to your sprite system
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Render sprite (MSX specific)
;; Input: HL = Transform pointer, C = sprite index
;; Output: None
;; Destroys: All registers
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
RENDER_SPRITE:
    ; Render sprite using MSX BIOS or direct VRAM access
    ; Implementation depends on your graphics system
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Sound System - Updates audio
;; Input: None
;; Output: None
;; Destroys: All registers
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
SOUND_SYSTEM:
    LD B, 0

SOUND_SYSTEM_LOOP:
    LD A, B
    CP MAX_ENTITIES
    RET NC
    
    ; Check if entity has sound component
    CALL GET_ENTITY_PTR
    LD A, (HL)
    OR A
    JP Z, SOUND_SYSTEM_NEXT
    
    LD A, B
    LD B, COMP_ID_SOUND
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JP Z, SOUND_SYSTEM_NEXT
    
    ; Process sound component
    ; Check if sound should be playing, update channels, etc.
    
SOUND_SYSTEM_NEXT:
    INC B
    JP SOUND_SYSTEM_LOOP

